/**
 * propers.js — Colectas y Prefacios Propios
 * Libro de Oración Común (2019), ACNA — Santa Eucaristía, Texto Estándar Anglicano
 *
 * PREFACES: transcritos del libro en español (LOC-10-10-23.md, líneas 3924-4086
 * del Libro de Oración Común 2019 convertido a Markdown). Cotejados carácter a
 * carácter el 2026-11-02 con bcp2019-tools/check-prefacios.js: coinciden los 31,
 * salvo dos desviaciones deliberadas, «Tú pides» (el libro trae «Tu pides», errata)
 * y el punto final del Santo Matrimonio. El libro da además tres prefacios que aquí
 * no figuran (la alternativa de «En Cualquier Tiempo», Día de Canadá o de la
 * Independencia, Día de Conmemoración o de los Caídos): el calendario no los emite.
 *
 * COLLECTS: FUENTE. Hasta 2026-11-02 estaban reconstruidas de memoria y NO coincidían con el libro (p. ej. el Propio 3
 * era otra oración). Ahora son, para las 5 de COLLECT_OFFICIAL (Miércoles de Ceniza, Domingo de Ramos, Jueves, Viernes
 * y Sábado Santo), el texto OFICIAL en español del libro (LOC-10-10-23.md); las otras 90 son TRADUCCIÓN del inglés
 * del BCP 2019 («Collects of the Christian Year», pp. 598-640 del libro en inglés), hecha en este proyecto POR
 * DECISIÓN EXPRESA DEL USUARIO (2026-11-02), que levantó para esto la regla 1 de CLAUDE.md (no traducir). Siguen
 * siendo traducciones propias, no texto oficial: están pendientes de revisión litúrgica (bcp2019/COLECTAS-REVISION.md)
 * y la liturgia lo avisa en una rúbrica (SHOW_COLLECT_TRANSLATION_NOTE en app.js).
 */

const BCPPropers = (() => {

  // ══════════════════════════════════════════════════════════════════════
  //  COLECTAS
  // ══════════════════════════════════════════════════════════════════════
  const COLLECTS = {
    advent1: 'Dios Todopoderoso, danos gracia para desechar las obras de las tinieblas y vestirnos con la armadura de la luz, ahora, en el tiempo de esta vida mortal en la cual tu Hijo Jesucristo vino a visitarnos con gran humildad; para que en el último día, cuando venga otra vez en su gloriosa majestad a juzgar a vivos y muertos, resucitemos a la vida inmortal; por aquel que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    advent2: 'Señor bendito, que hiciste que todas las Sagradas Escrituras se escribieran para nuestra enseñanza: Concédenos que de tal modo las oigamos, las leamos, las meditemos, las aprendamos y las asimilemos interiormente, que por la paciencia y el consuelo de tu santa Palabra abracemos y mantengamos siempre firme la bendita esperanza de la vida eterna, que nos has dado en nuestro Salvador Jesucristo; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    advent3: 'Oh Señor Jesucristo, que enviaste a tus mensajeros los profetas a predicar el arrepentimiento y a preparar el camino de nuestra salvación: Concede que los ministros y administradores de tus misterios preparen igualmente tu camino, volviendo los corazones de los desobedientes a la sabiduría de los justos, para que en tu segunda venida a juzgar al mundo seamos hallados un pueblo agradable ante tus ojos; porque con el Padre y el Espíritu Santo tú vives y reinas, un solo Dios, ahora y por siempre. Amén.',
    advent4: 'Despierta tu poder, oh Señor, y con gran fuerza ven entre nosotros; y puesto que estamos gravemente impedidos por nuestros pecados para correr la carrera que se nos ha propuesto, que tu abundante gracia y misericordia nos ayuden y libren con prontitud; por Jesucristo nuestro Señor, a quien, contigo y el Espíritu Santo, sea el honor y la gloria, ahora y por siempre. Amén.',
    christmas: 'Dios Todopoderoso, has dado a tu Hijo unigénito para que tomara nuestra naturaleza y naciera [en este día] de una Virgen pura: Concede que nosotros, que hemos nacido de nuevo y hemos sido hechos tus hijos por adopción y gracia, seamos renovados cada día por tu Espíritu Santo; por Jesucristo nuestro Señor, a quien, contigo y el mismo Espíritu, sea el honor y la gloria, ahora y por siempre. Amén.',
    christmasSunday: 'Dios Todopoderoso, has derramado sobre nosotros la nueva luz de tu Verbo encarnado: Concede que esta luz, encendida en nuestros corazones, resplandezca en nuestras vidas; por Jesucristo nuestro Señor, que vive y reina contigo en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    christmasSunday2: 'Oh Dios, que de modo admirable creaste la dignidad de la naturaleza humana, y de modo aún más admirable la restauraste: Concede que participemos de la vida divina de aquel que se humilló para compartir nuestra humanidad, tu Hijo Jesucristo nuestro Señor; que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    circumcision: 'Dios Todopoderoso, tu bendito Hijo cumplió por nosotros la alianza de la circuncisión, y recibió el Nombre que es sobre todo nombre: Danos gracia para llevar fielmente su Nombre, y para adorarlo con corazones puros conforme a la Nueva Alianza; que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    epiphany: 'Oh Dios, por la guía de una estrella manifestaste a tu Hijo único a los pueblos de la tierra: Guíanos, a quienes ahora te conocemos por la fe, hasta tu presencia, donde podamos ver tu gloria cara a cara; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    epiphany1: 'Padre eterno, en el bautismo de Jesús lo revelaste como tu Hijo, y tu Espíritu Santo descendió sobre él como una paloma: Concede que nosotros, que hemos nacido de nuevo del agua y del Espíritu, seamos fieles como tus hijos adoptivos; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    epiphany2: 'Dios Todopoderoso, cuyo Hijo, nuestro Salvador Jesucristo, es la luz del mundo: Concede que tu pueblo, iluminado por tu Palabra y Sacramentos, resplandezca con el fulgor de la gloria de Cristo, para que sea conocido, adorado y obedecido hasta los confines de la tierra; por Jesucristo nuestro Señor, que contigo y el Espíritu Santo vive y reina, un solo Dios, ahora y por siempre. Amén.',
    epiphany3: 'Danos gracia, oh Señor, para responder prontamente al llamado de nuestro Salvador Jesucristo y proclamar a todos los pueblos la Buena Nueva de su salvación, para que nosotros y el mundo entero percibamos la gloria de sus maravillosas obras; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    epiphany4: 'Oh Dios, tú sabes que estamos puestos en medio de muchos y graves peligros, y que por la fragilidad de nuestra naturaleza no siempre podemos mantenernos en pie: Concede que tu fortaleza y protección nos sostengan en todos los peligros y nos lleven a través de toda tentación; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    epiphany5: 'Oh Señor, Padre celestial nuestro, guarda continuamente a tu familia, la Iglesia, en tu verdadera religión, para que los que confiamos en la esperanza de tu gracia celestial seamos siempre defendidos por tu poderosa fuerza; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, ahora y por siempre. Amén.',
    epiphany6: 'Dios Todopoderoso, mira con misericordia a tu pueblo, para que por tu gran bondad sea gobernado y preservado siempre; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, ahora y por siempre. Amén.',
    epiphany7: 'Oh Dios, fortaleza de todos los que en ti confían: Acepta misericordiosamente nuestras oraciones y, puesto que por la debilidad de nuestra naturaleza mortal nada bueno podemos hacer sin ti, concédenos la ayuda de tu gracia, para que al guardar tus mandamientos te agrademos tanto en la voluntad como en las obras; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    epiphany8: 'Dios Todopoderoso y misericordioso, en tu bondad guárdanos, te rogamos, de todo lo que pueda dañarnos; para que, estando dispuestos de mente y cuerpo, cumplamos con corazón gozoso aquello que pertenece a tu propósito; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    transfiguration: 'Oh Dios, que antes de la pasión de tu Hijo unigénito revelaste su gloria sobre el monte santo: Concede que nosotros, contemplando por la fe la luz de su rostro, seamos fortalecidos para llevar nuestra cruz, y transformados a su semejanza de gloria en gloria; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',

    ashWednesday: 'Dios todopoderoso y eterno, que nada de lo que has hecho odias, y perdonas los pecados de todos los que se arrepienten: Crea y haz en nosotros corazones nuevos y contritos, para que, lamentando dignamente nuestros pecados y reconociendo nuestra miseria, podamos obtener de ti, el Dios de toda misericordia, perfecta remisión y perdón; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    lent1: 'Dios Todopoderoso, cuyo bendito Hijo fue llevado por el Espíritu para ser tentado por Satanás: Ven pronto en nuestra ayuda a los que somos asaltados por muchas tentaciones y, como conoces las debilidades de cada uno de nosotros, que cada cual te halle poderoso para salvar; por Jesucristo tu Hijo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    lent2: 'Dios Todopoderoso, tú sabes que no tenemos poder alguno en nosotros mismos para ayudarnos a nosotros mismos: Guárdanos tanto exteriormente en nuestros cuerpos como interiormente en nuestras almas, para que seamos defendidos de todas las adversidades que puedan sobrevenir al cuerpo, y de todos los malos pensamientos que puedan asaltar y dañar el alma; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    lent3: 'Padre celestial, nos has hecho para ti, y nuestros corazones están inquietos hasta que descansen en ti: Mira con compasión los deseos sinceros de tus siervos, y purifica nuestros afectos desordenados, para que contemplemos tu gloria eterna en el rostro de Cristo Jesús; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    lent4: 'Padre bondadoso, cuyo bendito Hijo Jesucristo descendió del cielo para ser el verdadero pan que da vida al mundo: Danos siempre este pan, para que él viva en nosotros y nosotros en él; que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    lent5: 'Dios Todopoderoso, solo tú puedes poner en orden las voluntades y los afectos desordenados de los pecadores: Concede a tu pueblo la gracia de amar lo que mandas y desear lo que prometes; para que, entre los rápidos y variados cambios de este mundo, nuestros corazones estén firmemente fijos allí donde se hallan los verdaderos gozos; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',

    palmSunday: 'Dios todopoderoso y eterno, en tu tierno amor por nosotros enviaste a tu Hijo, nuestro Salvador Jesucristo, para tomar sobre sí nuestra naturaleza y sufrir la muerte en la cruz, dándonos el ejemplo de su gran humildad: Concédenos misericordiosamente que caminemos en el camino de su sufrimiento, y lleguemos a participar de su resurrección; Por nuestro Señor Jesucristo, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    maundyThursday: 'Padre todopoderoso, cuyo amadísimo Hijo, la noche antes de sufrir, instituyó el sacramento de su Cuerpo y Sangre: Concédenos en tu misericordia que lo recibamos en recuerdo agradecido de Jesucristo nuestro Salvador, que en estos santos misterios nos da prenda de vida eterna; y quien vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    goodFriday: 'Dios todopoderoso, te rogamos que mires compasivamente a esta tu familia, por la cual nuestro Señor Jesucristo estuvo dispuesto a ser traicionado y entregado en manos de los pecadores, y sufrir la muerte en la Cruz; que ahora vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    holySaturday: 'Oh Dios, Creador del cielo y de la tierra: Concede que, así como el Cuerpo crucificado de tu amado Hijo fue puesto en el sepulcro y descansó en este santo sábado, esperemos con Él la llegada del tercer día, y resucitemos con Él a una vida nueva; por Jesucristo nuestro Señor. Amén.',

    easter: 'Dios Todopoderoso, que por medio de tu Hijo unigénito Jesucristo venciste la muerte y nos abriste la puerta de la vida eterna: Concede que nosotros, que celebramos con gozo el día de la resurrección del Señor, seamos librados del pecado y levantados de la muerte por tu Espíritu vivificante; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    easter2: 'Dios Todopoderoso y eterno, que en el misterio pascual estableciste la nueva alianza de reconciliación: Concede que todos los que hemos renacido a la comunión del Cuerpo de Cristo manifestemos en nuestras vidas lo que profesamos por la fe; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    easter3: 'Dios Todopoderoso, diste a tu único Hijo para que fuera para nosotros a la vez sacrificio por el pecado y ejemplo de vida piadosa: Danos gracia para recibir agradecidos sus inestimables beneficios, y para seguir cada día los bienaventurados pasos de su santísima vida; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    easter4: 'Oh Dios, cuyo Hijo Jesucristo es el Buen Pastor de tu pueblo: Concede que, cuando oigamos su voz, conozcamos a aquel que nos llama a cada uno por nuestro nombre, y lo sigamos adonde nos conduzca; que, contigo y el Espíritu Santo, vive y reina, un solo Dios, por los siglos de los siglos. Amén.',
    easter5: 'Dios Todopoderoso, a quien conocer verdaderamente es la vida eterna: Concédenos conocer tan perfectamente a tu Hijo Jesucristo como el camino, la verdad y la vida, que sigamos con firmeza sus pasos por el camino que conduce a la gloria eterna; por Jesucristo tu Hijo nuestro Señor, que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    easter6: 'Oh Dios, has preparado para los que te aman bienes tales que sobrepasan nuestro entendimiento: Infunde en nuestros corazones tal amor hacia ti, que, amándote en todas las cosas y por encima de todas las cosas, alcancemos tus promesas, que exceden todo lo que podemos desear; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    easter7: 'Oh Dios, Rey de gloria, que has exaltado con gran triunfo a tu único Hijo Jesucristo a tu reino en los cielos: No nos dejes desamparados, sino envíanos tu Espíritu Santo para fortalecernos, y elévanos al lugar adonde nuestro Salvador Cristo ha ido antes; que vive y reina contigo y el Espíritu Santo, un solo Dios, en gloria eterna. Amén.',
    ascension: 'Dios Todopoderoso, cuyo Hijo unigénito, nuestro Señor Jesucristo, ascendió al cielo: Concede que también nuestros corazones y mentes asciendan allí y moren continuamente con él; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    pentecost: 'Dios Todopoderoso, que en este día, por medio del derramamiento del Espíritu Santo, revelaste el camino de la vida eterna a toda raza y nación: Derrama de nuevo este don, para que por la predicación del Evangelio tu salvación llegue hasta los confines de la tierra; por Jesucristo nuestro Señor, que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    trinitySunday: 'Dios Todopoderoso y eterno, que nos has dado a tus siervos la gracia, por la confesión de una fe verdadera, de reconocer la gloria de la eterna Trinidad, y en el poder de tu divina Majestad adorar la Unidad: Mantennos firmes en esta fe y adoración, y llévanos finalmente a verte en tu gloria única y eterna, oh Padre; que con el Hijo y el Espíritu Santo vives y reinas, un solo Dios, por los siglos de los siglos. Amén.',

    proper3: 'Oh Señor, te suplicamos que nos oigas misericordiosamente, y concede que nosotros, a quienes has dado el deseo de orar, seamos por tu poderosa ayuda defendidos y consolados en todas nuestras adversidades; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper4: 'Oh Dios, protector de todos los que confían en ti, sin quien nada es fuerte, nada es santo: Aumenta y multiplica sobre nosotros tu misericordia, para que, contigo como nuestro gobernante y guía, pasemos de tal modo por las cosas temporales que no perdamos las eternas; concédelo, Padre celestial, por amor de tu Hijo Jesucristo, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper5: 'Concede, oh Señor, que el curso de este mundo sea ordenado tan pacíficamente por tu providencia, que tu Iglesia pueda servirte con gozo en tranquila confianza y piadosa paz; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper6: 'Oh Señor, de quien procede todo bien: Concédenos la inspiración de tu Espíritu Santo, para que pensemos siempre lo que es bueno, y por tu misericordiosa guía lo llevemos a cabo; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper7: 'Señor de todo poder y fuerza, autor y dador de todo bien: Injerta en nuestros corazones el amor de tu Nombre, aumenta en nosotros la verdadera religión, aliméntanos con toda bondad, y haz brotar en nosotros el fruto de las buenas obras; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper8: 'Oh Dios, tu providencia, que nunca falla, ordena todas las cosas en el cielo y en la tierra: Aparta de nosotros todo lo que nos dañe, y danos lo que nos sea provechoso; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper9: 'Concédenos, oh Señor, te rogamos, el espíritu para pensar y hacer siempre lo que es recto, para que nosotros, que sin ti nada bueno podemos hacer, seamos capacitados por ti para vivir conforme a tu voluntad; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper10: 'Que tus misericordiosos oídos, oh Señor, estén abiertos a las oraciones de tus humildes siervos; y, para que recibamos lo que pedimos, enséñanos por tu Espíritu Santo a pedir solo lo que te agrada; por Jesucristo nuestro Señor, que contigo y el mismo Espíritu vive y reina por los siglos de los siglos. Amén.',
    proper11: 'Oh Dios, tú manifiestas tu poder todopoderoso sobre todo al mostrar misericordia y compasión: Concédenos la plenitud de tu gracia, para que nosotros, corriendo a alcanzar tus promesas, lleguemos a ser partícipes de tu tesoro celestial; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper12: 'Dios Todopoderoso y eterno, tú estás siempre más dispuesto a oír que nosotros a orar, y a dar más de lo que deseamos o merecemos: Derrama sobre nosotros la abundancia de tu misericordia, perdonándonos aquello de lo cual nuestra conciencia tiene temor, y dándonos aquellos bienes que no somos dignos de pedir, sino por los méritos y la mediación de Jesucristo nuestro Salvador; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper13: 'Dios Todopoderoso y misericordioso, solo por tu gracia tu pueblo fiel te ofrece un servicio verdadero y digno de alabanza: Concede que corramos sin tropezar para alcanzar tus promesas celestiales; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    proper14: 'Dios Todopoderoso, danos el aumento de la fe, la esperanza y el amor; y, para que alcancemos lo que has prometido, haz que amemos lo que mandas; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper15: 'Guarda a tu Iglesia, oh Señor, con tu perpetua misericordia; y puesto que sin ti la fragilidad de nuestra naturaleza nos hace caer, guárdanos de todo lo dañoso, y llévanos a todo lo provechoso para nuestra salvación; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper16: 'Que tu continua misericordia, oh Señor, limpie y defienda a tu Iglesia; y, como no puede mantenerse segura sin tu ayuda, protégela y gobiérnala siempre con tu bondad; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper17: 'Oh Señor, te rogamos que tu gracia nos preceda y nos siga siempre, para que continuamente nos entreguemos a las buenas obras; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    proper18: 'Oh Señor Dios, concede a tu pueblo la gracia de resistir las tentaciones del mundo, la carne y el demonio, y de seguirte con corazón y mente puros, a ti, el único Dios; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    proper19: 'Oh Dios, puesto que sin ti no podemos agradarte, concede misericordiosamente que tu Espíritu Santo dirija y gobierne en todo nuestros corazones; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    proper20: 'Oh Señor, nos has enseñado que sin amor todas nuestras obras nada valen: Envía tu Espíritu Santo y derrama en nuestros corazones ese excelentísimo don de la caridad, el verdadero vínculo de la paz y de todas las virtudes, sin la cual quien vive es tenido por muerto ante ti; concédelo por amor de tu Hijo Jesucristo, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper21: 'Oh Señor misericordioso, concede a tu pueblo fiel perdón y paz, para que seamos limpios de todos nuestros pecados y te sirvamos con ánimo sereno; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    proper22: 'Guarda, oh Señor, a tu familia, la Iglesia, en continua piedad, para que por tu protección esté libre de todas las adversidades, y te sirva devotamente en buenas obras, para gloria de tu Nombre; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    proper23: 'Oh Dios, refugio y fortaleza nuestra, verdadera fuente de toda piedad: Escucha benignamente las devotas oraciones de tu Iglesia, y concede que lo que pedimos con fe lo obtengamos eficazmente; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    proper24: 'Líbranos, amado Padre, de la esclavitud de nuestros pecados, y en tu bondad y misericordia danos la libertad de esa vida abundante que nos has dado a conocer en nuestro Salvador Jesucristo; que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    proper25: 'Dios Todopoderoso y eterno, tú gobiernas todas las cosas en el cielo y en la tierra: Escucha misericordiosamente las súplicas de tu pueblo, y en nuestro tiempo concédenos tu paz; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper26: 'Concédenos, Señor, no andar ansiosos por las cosas terrenales, sino amar las celestiales; y aun ahora, mientras vivimos entre cosas que pasan, aferrarnos a las que han de permanecer; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper27: 'Oh Dios, cuyo bendito Hijo vino al mundo para destruir las obras del diablo y hacernos hijos de Dios y herederos de la vida eterna: Concede que, teniendo esta esperanza, nos purifiquemos como él es puro; para que, cuando venga otra vez con poder y gran gloria, seamos hechos semejantes a él en su eterno y glorioso reino; donde él vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper28: 'Despierta, oh Señor, las voluntades de tu pueblo fiel, para que, dando en abundancia el fruto de las buenas obras, sean abundantemente recompensados cuando nuestro Salvador Jesucristo venga a restaurar todas las cosas; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    proper29: 'Dios Todopoderoso y eterno, cuya voluntad es restaurar todas las cosas en tu amadísimo Hijo, Rey de reyes y Señor de señores: Concede misericordiosamente que los pueblos de la tierra, divididos y esclavizados por el pecado, sean libertados y reunidos bajo su benignísimo gobierno; que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',

    // ── SANTORAL FIJO ──
    '01-01': 'Dios Todopoderoso, tu bendito Hijo cumplió por nosotros la alianza de la circuncisión, y recibió el Nombre que es sobre todo nombre: Danos gracia para llevar fielmente su Nombre, y para adorarlo con corazones puros conforme a la Nueva Alianza; que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '01-18': 'Padre Todopoderoso, que inspiraste a Simón Pedro, el primero entre los apóstoles, a confesar a Jesús como Mesías e Hijo del Dios viviente: Mantén a tu Iglesia firme sobre la roca de esta fe, para que en unidad y paz proclamemos la única verdad y sigamos al único Señor, nuestro Salvador Jesucristo; que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '01-25': 'Oh Dios, por la predicación de tu apóstol Pablo hiciste resplandecer la luz del Evangelio por todo el mundo: Concede, te rogamos, que, teniendo presente su maravillosa conversión, te mostremos nuestra gratitud siguiendo su santa enseñanza; por Jesucristo nuestro Señor, que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '02-02': 'Dios Todopoderoso y siempre viviente, te pedimos humildemente que, así como tu Hijo unigénito fue presentado en este día en el templo en la sustancia de nuestra carne, así también seamos presentados ante ti con corazones puros y limpios por Jesucristo nuestro Señor; que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '02-24': 'Dios Todopoderoso, que en lugar de Judas escogiste a tu fiel siervo Matías para ser contado entre los Doce: Concede que tu Iglesia, librada de falsos apóstoles, sea siempre guiada y gobernada por pastores fieles y verdaderos; por Jesucristo nuestro Señor, que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '03-19': 'Oh Dios, que de la familia de tu siervo David suscitaste a José para ser guardián de tu Hijo encarnado y esposo de su madre virgen: Danos gracia para imitar su rectitud de vida y su obediencia a tus mandatos; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    '03-25': 'Derrama tu gracia en nuestros corazones, oh Señor, para que nosotros, que hemos conocido la encarnación de tu Hijo Jesucristo, anunciada por un ángel a la Virgen María, seamos llevados por su Cruz y pasión a la gloria de su resurrección; que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '04-25': 'Dios Todopoderoso, por mano de Marcos el evangelista has dado a tu Iglesia el Evangelio de Jesucristo: Te damos gracias por su testimonio, y te rogamos que nos des gracia para conocer la verdad, y no ser llevados de acá para allá por todo viento de falsa doctrina, para que conozcamos a Jesucristo como nuestro Señor y Salvador; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    '05-01': 'Dios Todopoderoso, diste a tus apóstoles Felipe y Santiago la gracia y la fuerza para dar testimonio de Jesús como el camino, la verdad y la vida: Concede que nosotros, teniendo presente su victoria de fe, glorifiquemos en la vida y en la muerte el Nombre de nuestro Señor Jesucristo; que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '05-31': 'Dios Todopoderoso, por cuya gracia Isabel se regocijó con la bendita Virgen María y la saludó como la madre del Señor: Mira con bondad a tus humildes siervos, para que, con María, magnifiquemos tu santo Nombre y nos alegremos de aclamar a su Hijo como nuestro Salvador; que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '06-11': 'Concede, oh Dios, que sigamos el ejemplo de tu fiel siervo Bernabé, quien, buscando no su propio renombre sino el bienestar de tu Iglesia, entregó generosamente su vida y sus bienes para el socorro de los pobres, y salió con valentía en misión para la propagación del Evangelio; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    '06-24': 'Dios Todopoderoso, por cuya providencia tu siervo Juan el Bautista nació de modo admirable, y fue enviado a preparar el camino de tu Hijo, nuestro Salvador, predicando el arrepentimiento: Haz que sigamos de tal modo su enseñanza y santa vida, que nos arrepintamos de verdad, reprendamos con audacia el vicio, suframos con paciencia por causa de la verdad, y proclamemos la venida de Jesucristo nuestro Señor; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    '06-29': 'Dios Todopoderoso, cuyos bienaventurados apóstoles Pedro y Pablo te glorificaron con su martirio: Concede que tu Iglesia, instruida por su enseñanza y ejemplo, y unida en unidad por tu Espíritu, permanezca siempre firme sobre el único fundamento, que es Jesucristo nuestro Señor; que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '07-22': 'Dios Todopoderoso, cuyo bendito Hijo devolvió a María Magdalena la salud del cuerpo y de la mente, y la llamó a ser testigo de su resurrección: Concede misericordiosamente que, por tu gracia, seamos sanados de todas nuestras dolencias y te conozcamos en el poder de su vida sin fin; que contigo y el Espíritu Santo vive y reina, un solo Dios, ahora y por siempre. Amén.',
    '07-25': 'Oh Dios bondadoso, tu siervo y apóstol Santiago fue el primero entre los Doce en sufrir el martirio por el Nombre de Jesucristo: Derrama sobre los líderes de tu Iglesia ese espíritu de servicio abnegado, por el cual puedan tener verdadera autoridad entre tu pueblo; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '08-06': 'Oh Dios, que en el monte santo revelaste a testigos escogidos a tu amadísimo Hijo, maravillosamente transfigurado, con vestiduras blancas y resplandecientes: Concede misericordiosamente que nosotros, librados de la inquietud de este mundo, contemplemos por la fe al Rey en su hermosura; que contigo y el Espíritu Santo vive y reina, un solo Dios, por los siglos de los siglos. Amén.',
    '08-15': 'Oh Dios, tomaste para ti a la bienaventurada Virgen María, madre de tu Hijo encarnado: Concede que nosotros, que hemos sido redimidos por su sangre, participemos con ella de la gloria de tu reino eterno; por Jesucristo nuestro Señor, que vive y reina contigo, en la unidad del Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '08-24': 'Dios Todopoderoso y eterno, diste a tu apóstol Bartolomé la gracia de creer verdaderamente y de predicar tu Palabra: Concede que tu Iglesia ame lo que él creyó y predique lo que él enseñó; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    '09-14': 'Dios Todopoderoso, cuyo Hijo, nuestro Salvador Jesucristo, fue levantado en alto sobre la Cruz para atraer a sí al mundo entero: Concede misericordiosamente que nosotros, que nos gloriamos en el misterio de nuestra redención, tengamos gracia para tomar nuestra cruz y seguirlo; que vive y reina contigo y el Espíritu Santo, un solo Dios, en gloria eterna. Amén.',
    '09-21': 'Señor Jesús, llamaste a Mateo del cobro de impuestos para que fuera tu apóstol y evangelista: Concédenos la gracia de abandonar todo deseo codicioso y amor desordenado de las riquezas, para que te sigamos como él lo hizo y proclamemos al mundo que nos rodea la buena nueva de tu salvación; porque con el Padre y el Espíritu Santo tú vives y reinas, un solo Dios, ahora y por siempre. Amén.',
    '09-29': 'Dios eterno, que has ordenado y constituido en maravilloso orden los ministerios de los ángeles y de los mortales: Concede misericordiosamente que, así como tus santos ángeles te sirven y adoran siempre en el cielo, así también, por tu designio, nos ayuden y defiendan aquí en la tierra; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    '10-18': 'Dios Todopoderoso, llamaste a tu siervo Lucas para ser evangelista y médico del alma: Concede que, por la medicina saludable de la doctrina que enseñó, sean sanadas todas las enfermedades de nuestras almas; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '10-23': 'Concede, oh Dios, que, siguiendo el ejemplo de tu apóstol Santiago el Justo, pariente de nuestro Señor, tu Iglesia se entregue continuamente a la oración y a la reconciliación de todos los que están en discordia y enemistad; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '10-28': 'Concede, oh Dios, que así como tus apóstoles Simón y Judas fueron fieles y celosos en su misión, así también nosotros, con ardiente devoción, demos a conocer el amor y la misericordia de nuestro Señor y Salvador Jesucristo; que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    '11-01': 'Dios Todopoderoso, has unido a tus elegidos en una sola comunión y compañía en el místico Cuerpo de tu Hijo: Danos gracia para seguir de tal modo a tus bienaventurados santos en toda vida virtuosa y piadosa, que lleguemos a esos gozos inefables que has preparado para los que verdaderamente te aman; por Jesucristo nuestro Señor, que contigo y el Espíritu Santo vive y reina, un solo Dios, en gloria eterna. Amén.',
    '11-30': 'Dios Todopoderoso, diste tal gracia a tu apóstol Andrés que obedeció prontamente el llamado de tu Hijo Jesucristo, y llevó consigo a su hermano: Danos a nosotros, llamados por tu santa Palabra, la gracia de seguirlo sin demora, y de llevar a los que están cerca de nosotros a su presencia bondadosa; que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '12-21': 'Dios siempre viviente, fortaleciste a tu apóstol Tomás con una fe firme y cierta en la resurrección de tu Hijo: Concédenos creer tan perfectamente y sin duda en Jesucristo, Señor nuestro y Dios nuestro, que nuestra fe nunca sea hallada deficiente ante ti; por aquel que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '12-26': 'Oh Señor glorioso, tu siervo Esteban alzó los ojos al cielo y oró por sus perseguidores: Concede que en todos nuestros sufrimientos aquí en la tierra amemos y perdonemos a nuestros enemigos, mirando con firmeza a Jesucristo nuestro Señor, que está sentado a tu diestra e intercede por nosotros; y que vive y reina contigo y el Espíritu Santo, un solo Dios, ahora y por siempre. Amén.',
    '12-27': 'Derrama sobre tu Iglesia, oh Señor, el resplandor de tu luz; para que, iluminados por la enseñanza de tu apóstol y evangelista Juan, andemos de tal modo en la luz de tu verdad, que al fin lleguemos a la plenitud de la vida eterna; por Jesucristo nuestro Señor, que vive y reina contigo y el Espíritu Santo, un solo Dios, por los siglos de los siglos. Amén.',
    '12-28': 'Dios Todopoderoso, de la boca de los niños manifiestas tu verdad, y por la muerte de los Santos Inocentes a manos de tiranos malvados muestras tu fuerza en nuestra debilidad: Te pedimos que hagas morir todo lo malo que hay en nosotros, y que nos fortalezcas de tal modo con tu gracia, que glorifiquemos tu santo Nombre por la inocencia de nuestras vidas y la constancia de nuestra fe hasta la muerte; por Jesucristo nuestro Señor, que murió por nosotros y ahora vive contigo y el Espíritu Santo, por los siglos de los siglos. Amén.',
  };

  // Procedencia de cada colecta. Estas cinco son el texto OFICIAL del libro en español, copiado de sus liturgias
  // (Miércoles de Ceniza y Semana Santa; el valor es la línea de LOC-10-10-23.md). TODAS las demás son TRADUCCIÓN
  // del inglés del BCP 2019 hecha en este proyecto (2026-11-02), porque la sección «Colectas del Año Cristiano» no
  // existe en español en los archivos del proyecto. Las traducciones están pendientes de revisión litúrgica.
  const COLLECT_OFFICIAL = { ashWednesday: 14497, palmSunday: 14801, maundyThursday: 14863, goodFriday: 14947, holySaturday: 15251 };
  const isCollectTranslated = key => !!COLLECTS[key] && !(key in COLLECT_OFFICIAL);

  // ══════════════════════════════════════════════════════════════════════
  //  PREFACIOS PROPIOS — transcritos del libro en español (líneas 3924-4086)
  // ══════════════════════════════════════════════════════════════════════
  const PREFACES = {
    lordsDay: { title: 'El Día del Señor', text: 'Por Jesucristo nuestro Señor, que el primer día de la semana venció a la muerte y al sepulcro, y por su gloriosa resurrección nos abrió el camino de la vida eterna.' },
    common: { title: 'En Cualquier Tiempo', text: 'Por Jesucristo nuestro Señor; porque él es tu Palabra viva desde antes del tiempo y para todos los tiempos; por él creaste todas las cosas, y por él haces nuevas todas las cosas.' },
    advent: { title: 'Adviento', text: 'Porque enviaste a tu Hijo amado para redimirnos del pecado y de la muerte, y para hacernos herederos en él de vida eterna; para que cuando vuelva con poder y gran gloria para juzgar al mundo, podamos sin vergüenza ni temor regocijarnos al contemplar su aparición.' },
    christmas: { title: 'Navidad', text: 'Porque diste a Jesucristo, tu único Hijo, para que naciera por nosotros; quien, por el Espíritu Santo y la Virgen María su madre, se hizo verdaderamente hombre, pero sin la mancha del pecado, para que seamos limpios del pecado y se nos otorgue el derecho de ser sus hijos.' },
    epiphany: { title: 'Epifanía', text: 'Mediante Jesucristo nuestro Señor que asumió nuestra carne mortal para revelar su gloria, para sacarnos de las tinieblas y llevarnos a su propia luz gloriosa.' },
    transfiguration: { title: 'Presentación, Anunciación y Transfiguración', text: 'Porque en el misterio del Verbo hecho carne, has hecho brillar una nueva luz en nuestros corazones, para dar el conocimiento de tu gloria en el rostro de tu Hijo Jesucristo nuestro Señor.' },
    lent: { title: 'Cuaresma', text: 'Tú pides a tus fieles que limpien sus corazones y se preparen con gozo para la fiesta pascual; para que, fervientes en la oración y en las obras de misericordia, y renovados por tu Palabra y los sacramentos, lleguen a la plenitud de la gracia que has preparado para los que te aman.' },
    holyWeek: { title: 'Semana Santa', text: 'Mediante Jesucristo nuestro Señor. Por nuestros pecados fue levantado sobre la Cruz, para atraer al mundo entero hacia él; y por su sufrimiento y muerte se convirtió en el autor de la salvación eterna para todos los que ponen su confianza en él.' },
    maundyThursday: { title: 'Jueves Santo', text: 'Mediante Jesucristo nuestro Señor. Habiendo amado a los suyos que estaban en el mundo, los amó hasta el extremo; y la noche antes de sufrir, instituyó estos santos misterios; para que nosotros, recibiendo los beneficios de su pasión y resurrección, seamos partícipes de su naturaleza divina.' },
    easter: { title: 'Pascua y Resurrección', text: 'Pero principalmente estamos obligados a alabarte por la gloriosa resurrección de tu Hijo Jesucristo, nuestro Señor; porque él es el verdadero Cordero pascual, que fue ofrecido por nosotros y quitó el pecado del mundo; quien con su muerte destruyó la muerte, y al resucitar, nos ganó la vida eterna.' },
    ascension: { title: 'Ascensión', text: 'Por tu amado Hijo Jesucristo nuestro Señor, quien después de su más gloriosa resurrección se apareció a sus Apóstoles, y en su presencia ascendió al cielo para prepararnos un lugar; para que donde él está, allí también podamos ascender y reinar con Él en gloria.' },
    pentecost: { title: 'Pentecostés', text: 'Por Jesucristo nuestro Señor; según cuya promesa más verdadera, el Espíritu Santo descendió del cielo, iluminando a los discípulos, para enseñarles y conducirlos a toda la verdad, dándoles valor y celo ferviente constantemente para predicar el Evangelio a todas las naciones; por el cual hemos sido sacados de las tinieblas y del error a la luz clara y al verdadero conocimiento de Ti y de tu Hijo Jesucristo.' },
    trinity: { title: 'Domingo de la Trinidad', text: 'Quien, con tu siempre-eterno Hijo y el Espíritu Santo, eres un solo Dios, un solo Señor, en Trinidad de Personas y en Unidad de Sustancia. Porque lo que creemos de tu gloria, oh Padre, creemos lo mismo de tu Hijo, y del Espíritu Santo, sin diferencia ni desigualdad.' },
    allSaints: { title: 'Todos los Santos', text: 'Porque en la multitud de tus santos, nos has rodeado de una nube de testigos tan grande de manera que nosotros, regocijándonos en su comunión, podamos correr con paciencia la carrera que tenemos por delante y, junto con ellos, recibir la corona imperecedera de gloria.' },
    christTheKing: { title: 'Cristo Rey', text: 'Por tu Hijo unigénito Jesucristo, Rey de reyes y Señor de señores; porque lo has sentado a tu diestra en gloria, y has sometido todas las cosas en contención bajo de sus pies, para que Él te las presente, oh Padre, perfectamente restauradas en belleza, verdad y amor.' },
    apostles: { title: 'Apóstoles y Ordenaciones', text: 'Por el gran Pastor de tu rebaño, Jesucristo nuestro Señor, quien después de su resurrección envió a sus apóstoles a predicar el Evangelio y enseñar a todas las naciones, y prometió estar con ellos siempre, hasta el fin de los tiempos.' },
    dedication: { title: 'Dedicación de una Iglesia', text: 'Por Jesucristo, nuestro gran Sumo Sacerdote, en quien somos edificados como piedras vivas de un templo santo, para que podamos ofrecer delante de Ti un sacrificio de alabanza y acción de gracias, santo y agradable a tus ojos.' },
    baptism: { title: 'Bautismo', text: 'Porque en Jesucristo nuestro Señor, nos has recibido como tus hijos e hijas, nos has hecho ciudadanos de tu reino y nos has dado el Espíritu Santo para guiarnos a toda verdad.' },
    marriage: { title: 'Santo Matrimonio', text: 'Porque en el amor de esposa y esposo, nos has dado una imagen de la Jerusalén celestial, adornada como una esposa para su esposo, tu Hijo Jesucristo nuestro Señor; que la ama y se entregó por ella, para hacer nueva toda la creación.' },
    burial: { title: 'Sepelio o Conmemoración de los Fieles Difuntos', text: 'Por Jesucristo nuestro Señor, que resucitó victorioso de entre los muertos y nos consuela con la esperanza bienaventurada de la vida eterna. Porque para tu pueblo fiel, oh Señor, la vida se transforma, no termina; y cuando nuestro cuerpo mortal descanse en la muerte, habrás preparado para nosotros una morada eterna en los cielos.' },
    penitential: { title: 'Ocasiones Penitenciales', text: 'Por Jesucristo nuestro Señor, que fue tentado en todo según nuestra semejanza, pero no pecó. Por su gracia podemos triunfar sobre todo mal y no vivir más sólo para nosotros, sino para Aquel que murió y resucitó por nosotros.' },
    thanksgiving: { title: 'Días de Rogativa o Acción de Gracias', text: 'Porque las maravillas de tu creación reflejan tu bondad y belleza; y tus dones de sol y lluvia, tiempo de siembra y cosecha, manifiestan tu constante amor y cuidado por todo lo que has hecho.' },
    martyr: { title: 'Común para un Mártir', text: 'Por el testimonio de tus mártires, que tomaron su cruz y te siguieron hasta la muerte, y revelaron tu poder perfeccionado en la debilidad humana.' },
    missionary: { title: 'Común para un Misionero o Evangelista', text: 'Por los dones de tu Espíritu Santo derramados sobre profetas y evangelistas, para proclamar el Evangelio hasta los confines de la tierra y para traer a todos los pueblos bajo el reinado de Jesucristo Nuestro Señor.' },
    pastor: { title: 'Común para un Pastor', text: 'Por Jesucristo, el gran pastor de las ovejas; en él llamas a pastores fieles y los unges con tu Espíritu Santo, para alimentar a tu rebaño con la Palabra y el Sacramento, y guiarlos por el camino de la vida eterna.' },
    teacher: { title: 'Común para un Maestro de la Fe', text: 'Porque has impartido dones de sabiduría y conocimiento a los que enseñan el Evangelio de palabra y de obra, para edificar el cuerpo de Cristo, hasta que todos alcancemos la unidad de la fe y del conocimiento del Hijo de Dios.' },
    religious: { title: 'Común para un Monástico o Religioso', text: 'Porque llamando a la vida consagrada a aquellos que lo dejan todo por tu reino, y que muestran en este mundo una anticipación de la vida abundante que prometes en el siglo venidero.' },
    ecumenist: { title: 'Común para un Ecuménico', text: 'Por tu Hijo Jesucristo nuestro Señor; en Él nos haces conocer tu verdad y nos unes con el vínculo de una fe y un bautismo, para que nos amemos unos a otros y manifestemos tu amor al mundo.' },
    socialReformer: { title: 'Común para un Restaurador de la Sociedad', text: 'Porque tú no te apartas nunca de nosotros y envías continuamente entre nosotros a quienes buscan justicia, defienden a los oprimidos, alimentan a los pobres y vendan a los quebrantados de corazón.' },
    churchReformer: { title: 'Común para un Reformador de la Iglesia', text: 'Porque tú, maestro de obras, nunca abandonas tu Iglesia, que has construido con piedras vivas; llamas a tus siervos fieles para restaurar sus antiguos muros y reunir sus murallas rotas, para que sean un templo santo de tu presencia.' },
    anyCommemoration: { title: 'Común para Cualquier Conmemoración', text: 'Por la gracia y la virtud manifestadas en [N. y todos] tus santos, que han sido los vasos escogidos de tu amor, y las luces del mundo en sus generaciones.' },
  };

  // ══════════════════════════════════════════════════════════════════════
  //  FUNCIONES DE BÚSQUEDA
  // ══════════════════════════════════════════════════════════════════════
  // Si no hay colecta para la clave, se AVISA — antes se devolvía en silencio
  // la del Propio 11, de modo que cualquier día sin colecta propia mostraba un
  // texto litúrgico ajeno sin que nada lo indicara. app.js ya resuelve la
  // colecta del Domingo precedente para las ferias (resolveCollectKey), así que
  // en el barrido 2024-2060 este aviso no se dispara ningún día: sólo existe
  // para que un hueco futuro sea visible en vez de silencioso.
  function getCollect(key) {
    return COLLECTS[key] || 'Colecta no disponible para este día.';
  }

  // Prefacio de cada fiesta fija, tal como lo rotula el libro en inglés bajo la colecta de cada uno de los 30
  // «Holy Days». El inglés tiene prefacios separados de la Presentación, la Anunciación y la Transfiguración;
  // el libro en español los reúne en uno solo (PREFACES.transfiguration). Gana sobre el domingo en que caiga.
  const FEAST_PREFACE = {
    '11-30': 'apostles', '12-21': 'apostles', '12-26': 'christmas', '12-27': 'christmas', '12-28': 'christmas',
    '01-01': 'transfiguration', '01-18': 'apostles', '01-25': 'apostles', '02-02': 'transfiguration', '02-24': 'apostles',
    '03-19': 'transfiguration', '03-25': 'transfiguration', '04-25': 'allSaints', '05-01': 'apostles', '05-31': 'transfiguration',
    '06-11': 'apostles', '06-24': 'advent', '06-29': 'apostles', '07-22': 'apostles', '07-25': 'apostles',
    '08-06': 'transfiguration', '08-15': 'christmas', '08-24': 'apostles', '09-14': 'holyWeek', '09-21': 'apostles',
    '09-29': 'trinity', '10-18': 'allSaints', '10-23': 'apostles', '10-28': 'apostles', '11-01': 'allSaints',
  };

  function getPreface(key, season) {
    if (FEAST_PREFACE[key]) return PREFACES[FEAST_PREFACE[key]];
    if (key === 'goodFriday' || key === 'holySaturday' || key === 'palmSunday' || (key && key.startsWith('holyWeekFeria'))) return PREFACES.holyWeek;
    if (key === 'maundyThursday') return PREFACES.maundyThursday;
    if (key === 'christmas' || key === 'christmasSunday' || key === 'christmasSunday2' || key === 'circumcision' || (key && key.startsWith('christmasFeria'))) return PREFACES.christmas;
    if (key === 'epiphany' || key === 'epiphany1' || (key && key.startsWith('epiphany'))) return PREFACES.epiphany;
    if (key === 'transfiguration') return PREFACES.transfiguration;
    // El Domingo después de la Ascensión (Pascua VII) lleva el prefacio de la Ascensión, no el de Pascua.
    if (key === 'ascension' || key === 'easter7') return PREFACES.ascension;
    if (key === 'easter' || (key && key.startsWith('easter'))) return PREFACES.easter;
    if (key === 'pentecost') return PREFACES.pentecost;
    if (key === 'trinitySunday') return PREFACES.trinity;
    if (key === 'proper29') return PREFACES.christTheKing;
    if (key && key.startsWith('advent')) return PREFACES.advent;
    // El Quinto Domingo de Cuaresma (lent5, «Domingo de Pasión») sigue en Cuaresma; la Semana Santa empieza el Domingo de Ramos.
    if (key === 'ashWednesday' || (key && key.startsWith('lent'))) return PREFACES.lent;
    // «There is no seasonal preface for the numbered propers. Prefaces of the Lord's Day are used on Sundays. No
    // preface is required on the weekdays of this season, except for Holy Days or commemorations.» Los domingos
    // (properN) llevan el del Día del Señor. En las ferias el libro no exige ninguno y se conserva «En Cualquier
    // Tiempo», para que la Eucaristía no quede sin prefacio.
    if (key && /^proper\d+$/.test(key)) return PREFACES.lordsDay;
    return PREFACES.common;
  }

  return { getCollect, getPreface, isCollectTranslated, COLLECTS, COLLECT_OFFICIAL, PREFACES };

})();
